-- live-schema.sql
-- Reconstructed DDL of the LIVE public schema of project effgebbqhkzaifwgdpoi ("Dental Clinic System").
-- Source: authenticated dashboard SQL editor, pg_catalog/information_schema reads only. Extracted 2026-11-25.
-- Contains NO data rows. For the isolated offline edition (fresh empty DB).
-- Live facts preserved here for the record: storage buckets patient-files and prints-files are PUBLIC on live.

SET client_min_messages = warning;

-- extensions present on live (plpgsql and supabase_vault are platform-managed; pg_stat_statements is server config)
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";
CREATE EXTENSION IF NOT EXISTS pgcrypto;

-- sequences on live not owned by identity columns
CREATE SEQUENCE IF NOT EXISTS public."prints_id_seq" AS bigint;
CREATE SEQUENCE IF NOT EXISTS public."insurances_id_seq" AS bigint;
CREATE SEQUENCE IF NOT EXISTS public."insurance_settlements_id_seq" AS bigint;
CREATE SEQUENCE IF NOT EXISTS public."insurance_payments_id_seq" AS bigint;

CREATE TABLE public."appointment_requests" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "patient_name" text,
  "patient_phone" text,
  "status" text DEFAULT 'pending'::text,
  "created_at" timestamp DEFAULT now(),
  "appointment_time" timestamp
);

CREATE TABLE public."assets" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id" text,
  "name" text,
  "price" double precision,
  "life" double precision,
  "roi" double precision
);

CREATE TABLE public."bills" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "beneficiary" text NOT NULL,
  "reason" text NOT NULL,
  "amount" numeric NOT NULL,
  "created_at" timestamptz DEFAULT now()
);

CREATE TABLE public."clinic_departments" (
  "id" uuid DEFAULT gen_random_uuid() NOT NULL,
  "user_id" uuid NOT NULL,
  "department_name" text NOT NULL,
  "created_at" timestamp DEFAULT now()
);

CREATE TABLE public."clinic_pages" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "clinic_name" text,
  "clinic_description" text,
  "clinic_logo" text,
  "phone" text,
  "whatsapp" text,
  "address" text,
  "working_hours" text,
  "facebook_url" text,
  "instagram_url" text,
  "website_url" text,
  "created_at" timestamp DEFAULT now(),
  "latitude" double precision,
  "longitude" double precision,
  "gallery_images" jsonb DEFAULT '[]'::jsonb,
  "working_schedule" jsonb
);

CREATE TABLE public."clinic_services" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "service_name" text NOT NULL,
  "service_price" numeric DEFAULT 0,
  "service_category" text,
  "service_description" text,
  "is_active" boolean DEFAULT true,
  "created_at" timestamptz DEFAULT now()
);

CREATE TABLE public."dental_works_catalog" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "work_name" text NOT NULL,
  "work_type" text NOT NULL,
  "lab_cost" numeric DEFAULT 0,
  "patient_amount" numeric DEFAULT 0,
  "created_at" timestamptz DEFAULT now(),
  "user_id" uuid
);

CREATE TABLE public."doctor_payments" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "doctor_id" bigint NOT NULL,
  "user_id" uuid NOT NULL,
  "amount" numeric DEFAULT 0 NOT NULL,
  "payment_date" timestamptz DEFAULT now() NOT NULL,
  "note" text,
  "created_at" timestamptz DEFAULT now() NOT NULL
);

CREATE TABLE public."doctor_works" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "doctor_id" bigint NOT NULL,
  "work_name" text NOT NULL,
  "work_cost" numeric DEFAULT 0,
  "doctor_percent" numeric DEFAULT 0,
  "doctor_profit" numeric DEFAULT 0,
  "created_at" timestamptz DEFAULT now(),
  "patient_name" text,
  "user_id" uuid
);

CREATE TABLE public."doctors" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "doctor_name" text NOT NULL,
  "specialization" text,
  "age" integer,
  "phone" text,
  "address" text,
  "created_at" timestamptz DEFAULT now(),
  "birth_date" date
);

CREATE TABLE public."drug_categories" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "name" text NOT NULL,
  "created_at" timestamptz DEFAULT now(),
  "user_id" uuid
);

CREATE TABLE public."drugs" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id" uuid,
  "category_id" bigint,
  "drug_name" text NOT NULL,
  "concentration" text,
  "dosage_form" text,
  "min_age" integer,
  "max_age" integer,
  "mg_per_kg" numeric,
  "frequency_per_day" integer,
  "max_daily_dose" numeric,
  "duration_days" integer,
  "notes" text,
  "created_at" timestamptz DEFAULT now(),
  "dosage_type" text,
  "concentration_unit" text DEFAULT 'mg'::text
);

CREATE TABLE public."expenses" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id" text,
  "name" text,
  "value" double precision
);

CREATE TABLE public."insurance_payments" (
  "id" bigint DEFAULT nextval('insurance_payments_id_seq'::regclass) NOT NULL,
  "user_id" uuid NOT NULL,
  "insurance_id" bigint NOT NULL,
  "amount" numeric NOT NULL,
  "payment_date" date DEFAULT CURRENT_DATE NOT NULL,
  "payment_method" text DEFAULT 'cash'::text,
  "notes" text,
  "created_at" timestamptz DEFAULT now() NOT NULL
);

CREATE TABLE public."insurance_services" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "insurance_id" bigint NOT NULL,
  "service_id" bigint NOT NULL,
  "discount_percent" numeric DEFAULT 0 NOT NULL,
  "created_at" timestamptz DEFAULT now()
);

CREATE TABLE public."insurance_settlements" (
  "id" bigint DEFAULT nextval('insurance_settlements_id_seq'::regclass) NOT NULL,
  "user_id" uuid NOT NULL,
  "insurance_id" bigint NOT NULL,
  "settlement_month" date NOT NULL,
  "is_settled" boolean DEFAULT false NOT NULL,
  "settled_at" timestamptz,
  "created_at" timestamptz DEFAULT now() NOT NULL
);

CREATE TABLE public."insurances" (
  "id" bigint DEFAULT nextval('insurances_id_seq'::regclass) NOT NULL,
  "user_id" uuid,
  "name" text NOT NULL,
  "percent" numeric DEFAULT 0,
  "created_at" timestamptz DEFAULT now()
);

CREATE TABLE public."inventory_items" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "item_name" text NOT NULL,
  "quantity" numeric DEFAULT 0 NOT NULL,
  "purchased_quantity" numeric DEFAULT 0 NOT NULL,
  "unit_price" numeric DEFAULT 0 NOT NULL,
  "total_purchase_price" numeric,
  "low_stock_threshold" numeric DEFAULT 1 NOT NULL,
  "created_at" timestamptz DEFAULT now() NOT NULL,
  "updated_at" timestamptz DEFAULT now() NOT NULL
);

CREATE TABLE public."inventory_purchases" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "inventory_item_id" bigint NOT NULL,
  "purchased_quantity" numeric NOT NULL,
  "unit_price" numeric NOT NULL,
  "total_purchase_price" numeric,
  "created_at" timestamptz DEFAULT now() NOT NULL,
  "purchase_invoice_id" bigint
);

CREATE TABLE public."inventory_service_usage" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "inventory_item_id" bigint NOT NULL,
  "clinic_service_id" bigint NOT NULL,
  "consumption_quantity" numeric DEFAULT 1 NOT NULL,
  "created_at" timestamptz DEFAULT now() NOT NULL
);

CREATE TABLE public."inventory_transactions" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "inventory_item_id" bigint NOT NULL,
  "quantity_change" numeric NOT NULL,
  "transaction_type" text NOT NULL,
  "reference_id" bigint,
  "notes" text,
  "created_at" timestamptz DEFAULT now() NOT NULL
);

CREATE TABLE public."lab_work_teeth" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "lab_work_id" bigint NOT NULL,
  "patient_id" bigint NOT NULL,
  "tooth_number" text NOT NULL,
  "created_at" timestamptz DEFAULT now()
);

CREATE TABLE public."lab_works" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "lab_id" bigint NOT NULL,
  "doctor_name" text,
  "patient_name" text,
  "work_name" text,
  "work_type" text,
  "lab_cost" numeric DEFAULT 0,
  "patient_amount" numeric DEFAULT 0,
  "delivery_date" date,
  "status" text DEFAULT 'Pending'::text,
  "notes" text,
  "created_at" timestamptz DEFAULT now(),
  "received" boolean DEFAULT false,
  "patient_id" bigint,
  "quantity" integer DEFAULT 1 NOT NULL
);

CREATE TABLE public."labs" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "lab_name" text,
  "specialization" text,
  "address" text,
  "phone" text,
  "created_at" timestamptz DEFAULT now()
);

CREATE TABLE public."notifications" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "type" text DEFAULT 'appointment_request'::text NOT NULL,
  "title" text NOT NULL,
  "message" text,
  "reference_id" bigint,
  "is_read" boolean DEFAULT false NOT NULL,
  "created_at" timestamptz DEFAULT now() NOT NULL
);

CREATE TABLE public."patient_files" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "patient_id" bigint,
  "treatment_details" text,
  "image_urls" text[],
  "xray_urls" text[],
  "created_at" timestamp DEFAULT now(),
  "image_type" text,
  "visit_id" bigint
);

CREATE TABLE public."patient_images" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "patient_id" bigint,
  "image_url" text,
  "image_type" text,
  "created_at" timestamptz DEFAULT now(),
  "user_id" uuid,
  "visit_id" bigint,
  "folder_id" text,
  "folder_name" text
);

CREATE TABLE public."patient_notes" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "patient_id" bigint,
  "note" text,
  "created_at" timestamptz DEFAULT now(),
  "user_id" uuid,
  "visit_id" bigint
);

CREATE TABLE public."patient_service_payments" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "service_id" bigint NOT NULL,
  "amount" numeric NOT NULL,
  "payment_date" timestamptz DEFAULT now(),
  "note" text,
  "created_at" timestamptz DEFAULT now(),
  "user_id" uuid,
  "previous_paid" numeric DEFAULT 0,
  "previous_remain" numeric DEFAULT 0,
  "new_paid" numeric DEFAULT 0,
  "new_remain" numeric DEFAULT 0,
  "action_type" text DEFAULT 'payment'::text,
  "payment_method" text DEFAULT 'cash'::text
);

CREATE TABLE public."patient_service_teeth" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "service_id" bigint,
  "tooth_number" text
);

CREATE TABLE public."patient_service_visits" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "service_id" bigint NOT NULL,
  "visit_id" bigint NOT NULL,
  "user_id" uuid NOT NULL,
  "is_original" boolean DEFAULT false NOT NULL,
  "created_at" timestamptz DEFAULT now() NOT NULL
);

CREATE TABLE public."patient_teeth" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "patient_id" bigint,
  "tooth_number" text,
  "tooth_status" text,
  "created_at" timestamptz DEFAULT now()
);

CREATE TABLE public."patient_visits" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "patient_id" bigint,
  "created_at" timestamp DEFAULT now(),
  "user_id" uuid,
  "visit_status" text DEFAULT 'قادم'::text,
  "appointment_start" timestamp,
  "appointment_end" timestamp,
  "visit_result" text DEFAULT 'waiting'::text,
  "is_deleted" boolean DEFAULT false,
  "department_id" uuid,
  "department_name" text,
  "patient_name" text,
  "patient_phone" text,
  "patient_age" integer,
  "visit_group_id" uuid,
  "visit_order" integer DEFAULT 1,
  "is_primary" boolean DEFAULT true,
  "visit_title" text,
  "reminder_sent_at" timestamptz,
  "reminder_status" text DEFAULT 'not_sent'::text,
  "reminder_message" text
);

CREATE TABLE public."patients" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "full_name" text,
  "phone" text,
  "gender" text,
  "address" text,
  "birth_date" date,
  "visit_date" date DEFAULT CURRENT_DATE,
  "medical_history" text,
  "dental_history" text,
  "created_at" timestamp DEFAULT now(),
  "user_id" uuid
);

CREATE TABLE public."patientt_services" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "patient_id" bigint,
  "service_name" text,
  "total_amount" numeric,
  "paid_amount" numeric,
  "remaining_amount" numeric,
  "created_at" timestamptz DEFAULT now(),
  "remain_amount" numeric,
  "user_id" uuid,
  "visit_id" bigint,
  "discount_amount" numeric DEFAULT 0 NOT NULL,
  "discount_type" text DEFAULT 'amount'::text NOT NULL,
  "discount_value" numeric DEFAULT 0 NOT NULL,
  "doctor_id" bigint,
  "doctor_percent" numeric DEFAULT 0,
  "doctor_amount" numeric DEFAULT 0,
  "quantity" bigint DEFAULT 1,
  "unit_price" numeric,
  "is_completed" boolean DEFAULT false NOT NULL,
  "insurance_id" bigint,
  "insurance_percent" numeric DEFAULT 0
);

CREATE TABLE public."pricing_settings" (
  "asset_days" text,
  "asset_hours" text,
  "exp_days" text,
  "exp_hours" text,
  "user_id" uuid
);

CREATE TABLE public."prints" (
  "id" bigint DEFAULT nextval('prints_id_seq'::regclass) NOT NULL,
  "user_id" uuid NOT NULL,
  "title" text NOT NULL,
  "type" text NOT NULL,
  "content" text,
  "image_url" text,
  "logo_url" text,
  "created_at" timestamp DEFAULT now(),
  "doctor_name" text,
  "doctor_title" text,
  "clinic_name" text
);

CREATE TABLE public."purchase_invoice_payments" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "purchase_invoice_id" bigint NOT NULL,
  "amount" numeric DEFAULT 0 NOT NULL,
  "payment_date" date DEFAULT CURRENT_DATE NOT NULL,
  "notes" text,
  "created_at" timestamptz DEFAULT now() NOT NULL
);

CREATE TABLE public."purchase_invoices" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "supplier_id" bigint,
  "invoice_number" text,
  "invoice_date" date DEFAULT CURRENT_DATE NOT NULL,
  "subtotal" numeric DEFAULT 0 NOT NULL,
  "discount" numeric DEFAULT 0 NOT NULL,
  "total_amount" numeric DEFAULT 0 NOT NULL,
  "paid_amount" numeric DEFAULT 0 NOT NULL,
  "remaining_amount" numeric DEFAULT 0 NOT NULL,
  "notes" text,
  "created_at" timestamptz DEFAULT now() NOT NULL,
  "updated_at" timestamptz DEFAULT now() NOT NULL,
  "discount_type" text DEFAULT 'amount'::text NOT NULL,
  "discount_value" numeric DEFAULT 0 NOT NULL
);

CREATE TABLE public."services" (
  "id" bigint GENERATED ALWAYS AS IDENTITY NOT NULL,
  "user_id" text,
  "name" text,
  "mat" double precision,
  "time" double precision,
  "profit" double precision
);

CREATE TABLE public."suppliers" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "supplier_name" text NOT NULL,
  "phone" text,
  "email" text,
  "address" text,
  "notes" text,
  "created_at" timestamptz DEFAULT now() NOT NULL,
  "updated_at" timestamptz DEFAULT now() NOT NULL
);

CREATE TABLE public."user_preferences" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "language" text DEFAULT 'en'::text NOT NULL,
  "theme" text DEFAULT 'dark'::text NOT NULL,
  "created_at" timestamptz DEFAULT now() NOT NULL,
  "updated_at" timestamptz DEFAULT now() NOT NULL
);

CREATE TABLE public."user_roles" (
  "id" uuid NOT NULL,
  "role" text DEFAULT 'reception'::text NOT NULL
);

CREATE TABLE public."visit_medications" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "drug_name" text NOT NULL,
  "dose" text,
  "duration" text,
  "instructions" text,
  "created_at" timestamptz DEFAULT now(),
  "patient_id" bigint,
  "visit_id" bigint,
  "drug_id" bigint
);

CREATE TABLE public."waiting_list" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" uuid NOT NULL,
  "patient_id" bigint,
  "patient_name" text NOT NULL,
  "age" integer,
  "phone" text,
  "created_at" timestamptz DEFAULT now() NOT NULL,
  "is_emergency" boolean DEFAULT false NOT NULL
);

