ALTER TABLE public."notifications" ADD CONSTRAINT "notifications_pkey" PRIMARY KEY (id);
ALTER TABLE public."patient_files" ADD CONSTRAINT "patient_files_pkey" PRIMARY KEY (id);
ALTER TABLE public."patient_images" ADD CONSTRAINT "patient_images_pkey" PRIMARY KEY (id);
ALTER TABLE public."patient_notes" ADD CONSTRAINT "patient_notes_pkey" PRIMARY KEY (id);
ALTER TABLE public."patient_service_payments" ADD CONSTRAINT "patient_service_payments_pkey" PRIMARY KEY (id);
