-- functions
CREATE OR REPLACE FUNCTION public.create_appointment_request_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ BEGIN INSERT INTO public.notifications ( user_id, type, title, message, reference_id ) VALUES ( NEW.user_id, 'appointment_request', 'New Appointment Request', 'Patient ' || NEW.patient_name || ' has requested an appointment.', NEW.id ); RETURN NEW; END; $function$;

CREATE OR REPLACE FUNCTION public.create_purchase_invoice(p_supplier_id bigint, p_invoice_number text, p_invoice_date date, p_discount numeric, p_paid_amount numeric, p_notes text, p_items jsonb) RETURNS bigint LANGUAGE plpgsql SET search_path TO 'public' AS $function$ DECLARE v_user_id uuid; v_invoice_id bigint; v_subtotal numeric := 0; v_discount numeric := 0; v_total_amount numeric := 0; v_paid_amount numeric := 0; v_remaining_amount numeric := 0; v_item jsonb; v_item_id bigint; v_item_name text; v_quantity numeric; v_unit_price numeric; v_line_total numeric; v_existing_quantity numeric; v_purchase_id bigint; BEGIN /* ===================================================== CURRENT USER ===================================================== */ v_user_id := auth.uid(); IF v_user_id IS NULL THEN RAISE EXCEPTION 'User is not authenticated'; END IF; /* ===================================================== BASIC VALIDATION ===================================================== */ IF p_supplier_id IS NULL THEN RAISE EXCEPTION 'Supplier is required'; END IF; IF p_invoice_date IS NULL THEN RAISE EXCEPTION 'Invoice date is required'; END IF; IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN RAISE EXCEPTION 'Invoice must contain at least one item'; END IF; /* ===================================================== VERIFY SUPPLIER BELONGS TO USER ===================================================== */ IF NOT EXISTS ( SELECT 1 FROM public.suppliers WHERE id = p_supplier_id AND user_id = v_user_id ) THEN RAISE EXCEPTION 'Invalid supplier'; END IF; /* ===================================================== DISCOUNT ===================================================== */ v_discount := GREATEST( COALESCE(p_discount, 0), 0 ); /* ===================================================== PAID ===================================================== */ v_paid_amount := GREATEST( COALESCE(p_paid_amount, 0), 0 ); /* ===================================================== FIRST PASS Calculate subtotal ===================================================== */ FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP v_quantity := COALESCE( (v_item ->> 'quantity')::numeric, 0 ); v_unit_price := COALESCE( (v_item ->> 'unit_price')::numeric, 0 ); IF v_quantity <= 0 THEN RAISE EXCEPTION 'Item quantity must be greater than zero'; END IF; IF v_unit_price < 0 THEN RAISE EXCEPTION 'Item unit price cannot be negative'; END IF; v_line_total := v_quantity * v_unit_price; v_subtotal := v_subtotal + v_line_total; END LOOP; /* ===================================================== TOTAL ===================================================== */ IF v_discount > v_subtotal THEN RAISE EXCEPTION 'Discount cannot exceed subtotal'; END IF; v_total_amount := v_subtotal - v_discount; /* ===================================================== PAID VALIDATION ===================================================== */ IF v_paid_amount > v_total_amount THEN RAISE EXCEPTION 'Paid amount cannot exceed total amount'; END IF; v_remaining_amount := v_total_amount - v_paid_amount; /* ===================================================== CREATE PURCHASE INVOICE ===================================================== */ INSERT INTO public.purchase_invoices ( user_id, supplier_id, invoice_number, invoice_date, subtotal, discount, total_amount, paid_amount, remaining_amount, notes ) VALUES ( v_user_id, p_supplier_id, NULLIF( TRIM(p_invoice_number), '' ), p_invoice_date, v_subtotal, v_discount, v_total_amount, v_paid_amount, v_remaining_amount, NULLIF( TRIM(p_notes), '' ) ) RETURNING id INTO v_invoice_id; /* ===================================================== SECOND PASS CREATE PURCHASE ROWS UPDATE INVENTORY CREATE TRANSACTIONS ===================================================== */ FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP /* ================================================= ITEM DATA ================================================= */ v_item_name := TRIM( COALESCE( v_item ->> 'item_name', '' ) ); v_quantity := (v_item ->> 'quantity')::numeric; v_unit_price := (v_item ->> 'unit_price')::numeric; v_line_total := v_quantity * v_unit_price; IF v_item_name = '' THEN RAISE EXCEPTION 'Item name is required'; END IF; /* ================================================= FIND EXISTING INVENTORY ITEM ================================================= */ SELECT id, quantity INTO v_item_id, v_existing_quantity FROM public.inventory_items WHERE user_id = v_user_id AND LOWER(TRIM(item_name)) = LOWER(v_item_name) LIMIT 1; /* ================================================= CREATE ITEM IF NOT EXISTS ================================================= */ IF v_item_id IS NULL THEN INSERT INTO public.inventory_items ( user_id, item_name, quantity, purchased_quantity, unit_price, low_stock_threshold ) VALUES ( v_user_id, v_item_name, v_quantity, v_quantity, v_unit_price, 1 ) RETURNING id INTO v_item_id; v_existing_quantity := 0; ELSE /* ============================================= UPDATE EXISTING ITEM ============================================= */ UPDATE public.inventory_items SET quantity = COALESCE(quantity, 0) + v_quantity, purchased_quantity = COALESCE(purchased_quantity, 0) + v_quantity, unit_price = v_unit_price, updated_at = NOW() WHERE id = v_item_id AND user_id = v_user_id; END IF; /* ================================================= PURCHASE ROW ================================================= */ INSERT INTO public.inventory_purchases ( user_id, inventory_item_id, purchase_invoice_id, purchased_quantity, unit_price, total_purchase_price ) VALUES ( v_user_id, v_item_id, v_invoice_id, v_quantity, v_unit_price, v_line_total ) RETURNING id INTO v_purchase_id; /* ================================================= INVENTORY TRANSACTION ================================================= */ INSERT INTO public.inventory_transactions ( user_id, inventory_item_id, quantity_change, transaction_type, reference_id, notes ) VALUES ( v_user_id, v_item_id, v_quantity, 'purchase', v_purchase_id, 'Purchase invoice #' || COALESCE( NULLIF( TRIM(p_invoice_number), '' ), v_invoice_id::text ) ); END LOOP; /* ===================================================== RETURN INVOICE ID ===================================================== */ RETURN v_invoice_id; END; $function$;

CREATE OR REPLACE FUNCTION public.deduct_inventory_for_patient_service() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $function$ declare usage_record record; service_id_value bigint; teeth_count int; total_consumption numeric; begin /* ========================================= TEETH COUNT = quantity field in patientt_services ========================================= */ teeth_count := GREATEST(COALESCE(NEW.quantity, 1), 1); /* ========================================= FIND CLINIC SERVICE BY NAME ========================================= */ select id into service_id_value from clinic_services where user_id = new.user_id and lower(trim(service_name)) = lower(trim(new.service_name)) limit 1; /* ========================================= SERVICE NOT FOUND ========================================= */ if service_id_value is null then return new; end if; /* ========================================= LOOP THROUGH ALL LINKED MATERIALS ========================================= */ for usage_record in select inventory_item_id, consumption_quantity from inventory_service_usage where user_id = new.user_id and clinic_service_id = service_id_value loop /* ========================================= CALCULATE TOTAL CONSUMPTION consumption per tooth × teeth count ========================================= */ total_consumption := usage_record.consumption_quantity * teeth_count; /* ========================================= DEDUCT FROM INVENTORY ========================================= */ update inventory_items set quantity = greatest(quantity - total_consumption, 0), updated_at = now() where id = usage_record.inventory_item_id and user_id = new.user_id; /* ========================================= SAVE TRANSACTION LOG ========================================= */ insert into inventory_transactions ( user_id, inventory_item_id, quantity_change, transaction_type, reference_id, notes ) values ( new.user_id, usage_record.inventory_item_id, -total_consumption, 'service_usage', new.id, 'Auto: ' || usage_record.consumption_quantity || ' per tooth × ' || teeth_count || ' teeth' ); end loop; return new; end; $function$;

CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER AS $function$ begin insert into public.profiles (id, email, full_name) values ( new.id, new.email, new.raw_user_meta_data->>'full_name' ); return new; end; $function$;

CREATE OR REPLACE FUNCTION public.update_clinic_whatsapp_updated_at() RETURNS trigger LANGUAGE plpgsql AS $function$ BEGIN NEW.updated_at = NOW(); RETURN NEW; END; $function$;

-- triggers
CREATE TRIGGER appointment_request_notification_trigger AFTER INSERT ON public.appointment_requests FOR EACH ROW EXECUTE FUNCTION create_appointment_request_notification();
CREATE TRIGGER trigger_deduct_inventory AFTER INSERT ON public.patientt_services FOR EACH ROW EXECUTE FUNCTION deduct_inventory_for_patient_service();

